INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) SELECT 'dedupe-20261003/regles/01-ne-jamais-decider-sous-pression',id,version,draft_json,'merge','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM content WHERE id='regles/01-ne-jamais-decider-sous-pression' AND version=1 AND updated_by='migration';
UPDATE content SET draft_json=json_set(draft_json,'$.detail','Lorsqu''une personne, un message ou un site vous pousse à décider immédiatement, ralentissez volontairement. Vérifiez l''information par un autre canal et accordez-vous quelques minutes avant toute action irréversible.

« Paiement immédiat », « compte bientôt bloqué » ou « dernier avertissement » cherchent parfois à déclencher une réaction avant la réflexion. Une urgence peut être réelle, mais elle ne doit jamais supprimer la vérification.

Le bon réflexe : si une demande vous presse, faites une pause, relisez-la et contrôlez son origine avant de répondre, payer ou cliquer.

Règle d''Or : Plus une demande vous pousse à agir vite, plus vous devez prendre le temps de la vérifier.'), published_json=CASE WHEN published_json IS NULL THEN NULL ELSE json_set(published_json,'$.detail','Lorsqu''une personne, un message ou un site vous pousse à décider immédiatement, ralentissez volontairement. Vérifiez l''information par un autre canal et accordez-vous quelques minutes avant toute action irréversible.

« Paiement immédiat », « compte bientôt bloqué » ou « dernier avertissement » cherchent parfois à déclencher une réaction avant la réflexion. Une urgence peut être réelle, mais elle ne doit jamais supprimer la vérification.

Le bon réflexe : si une demande vous presse, faites une pause, relisez-la et contrôlez son origine avant de répondre, payer ou cliquer.

Règle d''Or : Plus une demande vous pousse à agir vite, plus vous devez prendre le temps de la vérifier.') END, version=version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_by='migration', last_change='Merged editorial text into an existing equivalent rule.' WHERE id='regles/01-ne-jamais-decider-sous-pression' AND version=1 AND updated_by='migration';
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) SELECT 'dedupe-20261003/regles/02-verifiez-l-identite-avant-de-faire-confiance',id,version,draft_json,'merge','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM content WHERE id='regles/02-verifiez-l-identite-avant-de-faire-confiance' AND version=1 AND updated_by='migration';
UPDATE content SET draft_json=json_set(draft_json,'$.detail','Avant de transmettre une information sensible, de payer ou de modifier un accès, utilisez un moyen indépendant pour confirmer que vous parlez bien à la bonne personne ou à la bonne organisation.

Une signature, un logo, des couleurs familières ou un ton professionnel peuvent être reproduits. Un message qui semble venir d''un collègue, d''un fournisseur, d''une banque ou d''une administration n''est donc pas automatiquement authentique. Pour une demande d''argent, de coordonnées ou d''information sensible, répondre au message ne suffit pas.

Le bon réflexe : confirmez la demande par un numéro habituel ou un contact officiel dont vous connaissiez déjà les coordonnées.

Règle d''Or : Une demande inhabituelle doit toujours être vérifiée par un autre canal.'), published_json=CASE WHEN published_json IS NULL THEN NULL ELSE json_set(published_json,'$.detail','Avant de transmettre une information sensible, de payer ou de modifier un accès, utilisez un moyen indépendant pour confirmer que vous parlez bien à la bonne personne ou à la bonne organisation.

Une signature, un logo, des couleurs familières ou un ton professionnel peuvent être reproduits. Un message qui semble venir d''un collègue, d''un fournisseur, d''une banque ou d''une administration n''est donc pas automatiquement authentique. Pour une demande d''argent, de coordonnées ou d''information sensible, répondre au message ne suffit pas.

Le bon réflexe : confirmez la demande par un numéro habituel ou un contact officiel dont vous connaissiez déjà les coordonnées.

Règle d''Or : Une demande inhabituelle doit toujours être vérifiée par un autre canal.') END, version=version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_by='migration', last_change='Merged editorial text into an existing equivalent rule.' WHERE id='regles/02-verifiez-l-identite-avant-de-faire-confiance' AND version=1 AND updated_by='migration';
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) SELECT 'dedupe-20261003/regles/17-verifiez-toute-information-importante-produite-par-une-ia',id,version,draft_json,'merge','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM content WHERE id='regles/17-verifiez-toute-information-importante-produite-par-une-ia' AND version=1 AND updated_by='migration';
UPDATE content SET draft_json=json_set(draft_json,'$.detail','Pour une décision importante, vérifiez les chiffres, dates, citations et affirmations auprès d''une source fiable avant de les utiliser. Une IA peut mélanger des informations, inventer une référence, mal interpréter un document ou présenter une réponse dépassée, même si son texte paraît assuré.

Le bon réflexe : utilisez l''IA pour chercher ou réfléchir, puis contrôlez les faits importants auprès de sources fiables.

Règle d''Or : Une réponse d''IA n''est pas une preuve : vérifiez toujours ce qui compte.'), published_json=CASE WHEN published_json IS NULL THEN NULL ELSE json_set(published_json,'$.detail','Pour une décision importante, vérifiez les chiffres, dates, citations et affirmations auprès d''une source fiable avant de les utiliser. Une IA peut mélanger des informations, inventer une référence, mal interpréter un document ou présenter une réponse dépassée, même si son texte paraît assuré.

Le bon réflexe : utilisez l''IA pour chercher ou réfléchir, puis contrôlez les faits importants auprès de sources fiables.

Règle d''Or : Une réponse d''IA n''est pas une preuve : vérifiez toujours ce qui compte.') END, version=version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_by='migration', last_change='Merged editorial text into an existing equivalent rule.' WHERE id='regles/17-verifiez-toute-information-importante-produite-par-une-ia' AND version=1 AND updated_by='migration';
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) SELECT 'dedupe-20261003/regles/18-ne-confiez-pas-a-une-ia-ce-que-vous-ne-publieriez-pas',id,version,draft_json,'merge','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM content WHERE id='regles/18-ne-confiez-pas-a-une-ia-ce-que-vous-ne-publieriez-pas' AND version=1 AND updated_by='migration';
UPDATE content SET draft_json=json_set(draft_json,'$.detail','Avant de transmettre un document, un secret commercial ou une information personnelle, vérifiez les conditions du service et supprimez les éléments inutiles. Les contrats, les données clients, les informations bancaires ou les secrets professionnels peuvent avoir des conséquences importantes s''ils sortent de leur environnement prévu.

Le bon réflexe : vérifiez les règles de confidentialité du service et demandez-vous si vous pourriez confier cette information à un tiers.

Règle d''Or : Une IA ne doit jamais devenir le coffre-fort de données que vous n''auriez pas le droit de partager.'), published_json=CASE WHEN published_json IS NULL THEN NULL ELSE json_set(published_json,'$.detail','Avant de transmettre un document, un secret commercial ou une information personnelle, vérifiez les conditions du service et supprimez les éléments inutiles. Les contrats, les données clients, les informations bancaires ou les secrets professionnels peuvent avoir des conséquences importantes s''ils sortent de leur environnement prévu.

Le bon réflexe : vérifiez les règles de confidentialité du service et demandez-vous si vous pourriez confier cette information à un tiers.

Règle d''Or : Une IA ne doit jamais devenir le coffre-fort de données que vous n''auriez pas le droit de partager.') END, version=version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_by='migration', last_change='Merged editorial text into an existing equivalent rule.' WHERE id='regles/18-ne-confiez-pas-a-une-ia-ce-que-vous-ne-publieriez-pas' AND version=1 AND updated_by='migration';
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/76-un-mot-de-passe-visible-est-deja-un-mot-de-passe-compromis','{"id":76,"number":"76","slug":"76-un-mot-de-passe-visible-est-deja-un-mot-de-passe-compromis","title":"Un mot de passe visible est déjà un mot de passe compromis.","summary":"Un secret aperçu dans une photo, une capture ou un document partagé ne l''est plus.","detail":"Un post-it posé sur un bureau, une capture d''écran, une photo publiée en ligne ou un document partagé peuvent révéler un mot de passe sans aucune attaque informatique. Le risque augmente encore si ce secret est réutilisé sur plusieurs services.\n\nLe bon réflexe : considérez comme compromis tout mot de passe vu par une autre personne. Remplacez-le et utilisez un secret différent pour chaque service important.\n\nRègle d''Or : Un mot de passe visible est déjà un mot de passe compromis.","categoryId":"cybersecurite","order":75,"subcategory":"","homeRank":0}','{"id":76,"number":"76","slug":"76-un-mot-de-passe-visible-est-deja-un-mot-de-passe-compromis","title":"Un mot de passe visible est déjà un mot de passe compromis.","summary":"Un secret aperçu dans une photo, une capture ou un document partagé ne l''est plus.","detail":"Un post-it posé sur un bureau, une capture d''écran, une photo publiée en ligne ou un document partagé peuvent révéler un mot de passe sans aucune attaque informatique. Le risque augmente encore si ce secret est réutilisé sur plusieurs services.\n\nLe bon réflexe : considérez comme compromis tout mot de passe vu par une autre personne. Remplacez-le et utilisez un secret différent pour chaque service important.\n\nRègle d''Or : Un mot de passe visible est déjà un mot de passe compromis.","categoryId":"cybersecurite","order":75,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
