INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/77-un-qr-code-n-est-pas-un-lien-de-confiance','{"id":77,"number":"77","slug":"77-un-qr-code-n-est-pas-un-lien-de-confiance","title":"Un QR Code n''est pas un lien de confiance.","summary":"Son apparence ne garantit pas que sa destination est sûre.","detail":"Un QR Code peut renvoyer vers un site légitime ou vers une imitation conçue pour récupérer un mot de passe ou des coordonnées bancaires. L''adresse réelle est souvent moins visible qu''un lien classique.\n\nLe bon réflexe : vérifiez la destination avant de vous connecter ou de transmettre la moindre information.\n\nRègle d''Or : Un QR Code n''est pas un lien de confiance : vérifiez sa destination avant de l''ouvrir.","categoryId":"cybersecurite","order":76,"subcategory":"","homeRank":0}','{"id":77,"number":"77","slug":"77-un-qr-code-n-est-pas-un-lien-de-confiance","title":"Un QR Code n''est pas un lien de confiance.","summary":"Son apparence ne garantit pas que sa destination est sûre.","detail":"Un QR Code peut renvoyer vers un site légitime ou vers une imitation conçue pour récupérer un mot de passe ou des coordonnées bancaires. L''adresse réelle est souvent moins visible qu''un lien classique.\n\nLe bon réflexe : vérifiez la destination avant de vous connecter ou de transmettre la moindre information.\n\nRègle d''Or : Un QR Code n''est pas un lien de confiance : vérifiez sa destination avant de l''ouvrir.","categoryId":"cybersecurite","order":76,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
