INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas','{"id":78,"number":"78","slug":"78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas","title":"Ne collez pas une commande que vous ne comprenez pas.","summary":"Une commande peut modifier vos fichiers ou transmettre des informations.","detail":"Une commande ou un script présenté comme une solution rapide peut installer un programme, modifier des fichiers ou transmettre des informations sans que vous le remarquiez. Une présentation sérieuse ne garantit pas son innocuité.\n\nLe bon réflexe : comprenez ce que fait une commande et vérifiez sa provenance avant de l''exécuter. En cas de doute, ne l''exécutez pas.\n\nRègle d''Or : Ne collez jamais une commande trouvée sur Internet dans votre terminal sans savoir exactement ce qu''elle fait.","categoryId":"cybersecurite","order":77,"subcategory":"","homeRank":0}','{"id":78,"number":"78","slug":"78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas","title":"Ne collez pas une commande que vous ne comprenez pas.","summary":"Une commande peut modifier vos fichiers ou transmettre des informations.","detail":"Une commande ou un script présenté comme une solution rapide peut installer un programme, modifier des fichiers ou transmettre des informations sans que vous le remarquiez. Une présentation sérieuse ne garantit pas son innocuité.\n\nLe bon réflexe : comprenez ce que fait une commande et vérifiez sa provenance avant de l''exécuter. En cas de doute, ne l''exécutez pas.\n\nRègle d''Or : Ne collez jamais une commande trouvée sur Internet dans votre terminal sans savoir exactement ce qu''elle fait.","categoryId":"cybersecurite","order":77,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/regles/78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas','regles/78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas',1,'{"id":78,"number":"78","slug":"78-ne-collez-pas-une-commande-que-vous-ne-comprenez-pas","title":"Ne collez pas une commande que vous ne comprenez pas.","summary":"Une commande peut modifier vos fichiers ou transmettre des informations.","detail":"Une commande ou un script présenté comme une solution rapide peut installer un programme, modifier des fichiers ou transmettre des informations sans que vous le remarquiez. Une présentation sérieuse ne garantit pas son innocuité.\n\nLe bon réflexe : comprenez ce que fait une commande et vérifiez sa provenance avant de l''exécuter. En cas de doute, ne l''exécutez pas.\n\nRègle d''Or : Ne collez jamais une commande trouvée sur Internet dans votre terminal sans savoir exactement ce qu''elle fait.","categoryId":"cybersecurite","order":77,"subcategory":"","homeRank":0}','migration','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise','{"id":79,"number":"79","slug":"79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise","title":"Une donnée qui a fuité doit être considérée comme compromise.","summary":"Une donnée divulguée peut être recoupée et réutilisée bien plus tard.","detail":"Une adresse e-mail, un numéro de téléphone ou une ancienne information personnelle peuvent être associés à d''autres données et réutilisés longtemps après l''incident. Une donnée sortie de votre contrôle ne peut plus être considérée comme secrète.\n\nLe bon réflexe : après une fuite, remplacez les informations qui peuvent l''être et restez attentif aux messages, appels et tentatives de connexion inhabituels.\n\nRègle d''Or : Une donnée qui a fuité doit être considérée comme compromise.","categoryId":"cybersecurite","order":78,"subcategory":"","homeRank":0}','{"id":79,"number":"79","slug":"79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise","title":"Une donnée qui a fuité doit être considérée comme compromise.","summary":"Une donnée divulguée peut être recoupée et réutilisée bien plus tard.","detail":"Une adresse e-mail, un numéro de téléphone ou une ancienne information personnelle peuvent être associés à d''autres données et réutilisés longtemps après l''incident. Une donnée sortie de votre contrôle ne peut plus être considérée comme secrète.\n\nLe bon réflexe : après une fuite, remplacez les informations qui peuvent l''être et restez attentif aux messages, appels et tentatives de connexion inhabituels.\n\nRègle d''Or : Une donnée qui a fuité doit être considérée comme compromise.","categoryId":"cybersecurite","order":78,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/regles/79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise','regles/79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise',1,'{"id":79,"number":"79","slug":"79-une-donnee-qui-a-fuite-doit-etre-consideree-comme-compromise","title":"Une donnée qui a fuité doit être considérée comme compromise.","summary":"Une donnée divulguée peut être recoupée et réutilisée bien plus tard.","detail":"Une adresse e-mail, un numéro de téléphone ou une ancienne information personnelle peuvent être associés à d''autres données et réutilisés longtemps après l''incident. Une donnée sortie de votre contrôle ne peut plus être considérée comme secrète.\n\nLe bon réflexe : après une fuite, remplacez les informations qui peuvent l''être et restez attentif aux messages, appels et tentatives de connexion inhabituels.\n\nRègle d''Or : Une donnée qui a fuité doit être considérée comme compromise.","categoryId":"cybersecurite","order":78,"subcategory":"","homeRank":0}','migration','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse','{"id":80,"number":"80","slug":"80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse","title":"Une sauvegarde jamais restaurée n''est qu''une promesse.","summary":"Seule une restauration permet de savoir si vos fichiers sont récupérables.","detail":"Un disque peut être défectueux, une archive corrompue ou une sauvegarde rendue inaccessible par une attaque. Un statut « réussi » ne prouve pas que vos fichiers pourront être récupérés.\n\nLe bon réflexe : restaurez régulièrement quelques fichiers et vérifiez qu''ils sont bien utilisables.\n\nRègle d''Or : Une sauvegarde jamais restaurée n''est qu''une promesse.","categoryId":"cybersecurite","order":79,"subcategory":"","homeRank":0}','{"id":80,"number":"80","slug":"80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse","title":"Une sauvegarde jamais restaurée n''est qu''une promesse.","summary":"Seule une restauration permet de savoir si vos fichiers sont récupérables.","detail":"Un disque peut être défectueux, une archive corrompue ou une sauvegarde rendue inaccessible par une attaque. Un statut « réussi » ne prouve pas que vos fichiers pourront être récupérés.\n\nLe bon réflexe : restaurez régulièrement quelques fichiers et vérifiez qu''ils sont bien utilisables.\n\nRègle d''Or : Une sauvegarde jamais restaurée n''est qu''une promesse.","categoryId":"cybersecurite","order":79,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/regles/80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse','regles/80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse',1,'{"id":80,"number":"80","slug":"80-une-sauvegarde-jamais-restauree-n-est-qu-une-promesse","title":"Une sauvegarde jamais restaurée n''est qu''une promesse.","summary":"Seule une restauration permet de savoir si vos fichiers sont récupérables.","detail":"Un disque peut être défectueux, une archive corrompue ou une sauvegarde rendue inaccessible par une attaque. Un statut « réussi » ne prouve pas que vos fichiers pourront être récupérés.\n\nLe bon réflexe : restaurez régulièrement quelques fichiers et vérifiez qu''ils sont bien utilisables.\n\nRègle d''Or : Une sauvegarde jamais restaurée n''est qu''une promesse.","categoryId":"cybersecurite","order":79,"subcategory":"","homeRank":0}','migration','migration',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/81-une-information-anodine-peut-devenir-sensible-une-fois-recoupee','{"id":81,"number":"81","slug":"81-une-information-anodine-peut-devenir-sensible-une-fois-recoupee","title":"Une information anodine peut devenir sensible une fois recoupée.","summary":"Des détails publiés séparément peuvent révéler bien plus une fois réunis.","detail":"Votre prénom, votre ville, votre métier, une photo ou le nom de votre entreprise peuvent sembler inoffensifs pris séparément. Associés, ces détails peuvent révéler vos habitudes, vos relations ou votre lieu de travail et faciliter une tentative de manipulation.\n\nLe bon réflexe : avant de publier, pensez à ce qu''une personne pourrait déduire en combinant cette information avec tout ce qui est déjà accessible.\n\nRègle d''Or : Une information anodine seule peut devenir sensible une fois recoupée avec d''autres.","categoryId":"cybersecurite","order":80,"subcategory":"","homeRank":0}','{"id":81,"number":"81","slug":"81-une-information-anodine-peut-devenir-sensible-une-fois-recoupee","title":"Une information anodine peut devenir sensible une fois recoupée.","summary":"Des détails publiés séparément peuvent révéler bien plus une fois réunis.","detail":"Votre prénom, votre ville, votre métier, une photo ou le nom de votre entreprise peuvent sembler inoffensifs pris séparément. Associés, ces détails peuvent révéler vos habitudes, vos relations ou votre lieu de travail et faciliter une tentative de manipulation.\n\nLe bon réflexe : avant de publier, pensez à ce qu''une personne pourrait déduire en combinant cette information avec tout ce qui est déjà accessible.\n\nRègle d''Or : Une information anodine seule peut devenir sensible une fois recoupée avec d''autres.","categoryId":"cybersecurite","order":80,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
