INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by,last_change) VALUES('regles/82-avant-de-transmettre-une-donnee-personnelle-verifiez-qu-elle-est-necessaire','{"id":82,"number":"82","slug":"82-avant-de-transmettre-une-donnee-personnelle-verifiez-qu-elle-est-necessaire","title":"Avant de transmettre une donnée personnelle, vérifiez qu''elle est nécessaire.","summary":"Un formulaire qui demande une information ne prouve pas qu''elle est indispensable.","detail":"Une date de naissance, une adresse, un numéro de téléphone ou une copie de document peuvent être conservés, recoupés ou compromis. Le fait qu''un champ existe ne signifie pas que vous devez le remplir.\n\nLe bon réflexe : demandez-vous à quoi sert la donnée et si le service en a réellement besoin avant de la transmettre.\n\nRègle d''Or : Avant de transmettre une donnée personnelle, demandez-vous si le service en a réellement besoin.","categoryId":"ia-numerique","order":81,"subcategory":"","homeRank":0}','{"id":82,"number":"82","slug":"82-avant-de-transmettre-une-donnee-personnelle-verifiez-qu-elle-est-necessaire","title":"Avant de transmettre une donnée personnelle, vérifiez qu''elle est nécessaire.","summary":"Un formulaire qui demande une information ne prouve pas qu''elle est indispensable.","detail":"Une date de naissance, une adresse, un numéro de téléphone ou une copie de document peuvent être conservés, recoupés ou compromis. Le fait qu''un champ existe ne signifie pas que vous devez le remplir.\n\nLe bon réflexe : demandez-vous à quoi sert la donnée et si le service en a réellement besoin avant de la transmettre.\n\nRègle d''Or : Avant de transmettre une donnée personnelle, demandez-vous si le service en a réellement besoin.","categoryId":"ia-numerique","order":81,"subcategory":"","homeRank":0}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','');
